from datetime import datetime, timedelta

# Configuration
participants = {
    "Cheryl": {
        "Monday": [("09:00", "09:30"), ("11:30", "13:00"), ("15:30", "16:00")],
        "Tuesday": [("15:00", "15:30")],
        # Cheryl cannot meet on Wednesday (no availability)
    },
    "Kyle": {
        "Monday": [("09:00", "17:00")],
        "Tuesday": [("09:30", "17:00")],
        "Wednesday": [("09:00", "09:30"), ("10:00", "13:00"),
                      ("13:30", "14:00"), ("14:30", "17:00")],
    },
}
work_start = "09:00"
work_end = "17:00"
meeting_minutes = 30
allowed_days = ["Monday", "Tuesday", "Wednesday"]

def to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

work_start_min = to_min(work_start)
work_end_min = to_min(work_end)

def invert_busy(busy_intervals):
    """Given busy intervals (list of (start, end) strings) within work hours,
       return free intervals as list of (start_min, end_min)."""
    busy = sorted((to_min(s), to_min(e)) for s, e in busy_intervals)
    free = []
    cur = work_start_min
    for b_start, b_end in busy:
        if b_start > cur:
            free.append((cur, b_start))
        cur = max(cur, b_end)
    if cur < work_end_min:
        free.append((cur, work_end_min))
    return free

def intersect(intervals_a, intervals_b):
    """Intersect two lists of (start, end) minute intervals."""
    i, j = 0, 0
    res = []
    while i < len(intervals_a) and j < len(intervals_b):
        a_start, a_end = intervals_a[i]
        b_start, b_end = intervals_b[j]
        start = max(a_start, b_start)
        end = min(a_end, b_end)
        if start < end:
            res.append((start, end))
        if a_end <= b_end:
            i += 1
        else:
            j += 1
    return res

def find_slot():
    for day in allowed_days:
        # Skip days where any participant has no entry (treated as no availability)
        if any(day not in participants[p] for p in participants):
            continue
        # Compute free intervals per participant
        common_free = [(work_start_min, work_end_min)]
        for p in participants:
            busy = participants[p].get(day, [])
            free = invert_busy(busy)
            common_free = intersect(common_free, free)
            if not common_free:
                break
        # Look for a slot of required length
        for start, end in common_free:
            if end - start >= meeting_minutes:
                meeting_start = start
                meeting_end = start + meeting_minutes
                return [day, to_str(meeting_start), to_str(meeting_end)]
    return None

result = find_slot()
