import sys

# Helper functions
def to_min(t):
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m):
    h = m // 60
    mi = m % 60
    return f"{h:02d}:{mi:02d}"

def complement(intervals, start, end):
    """Return free intervals within [start, end) given occupied intervals (list of (s,e))."""
    free = []
    cur = start
    for s, e in sorted(intervals):
        if s > cur:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < end:
        free.append((cur, end))
    return free

def intersect_two(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s1, e1 = a[i]
        s2, e2 = b[j]
        s = max(s1, s2)
        e = min(e1, e2)
        if s < e:
            res.append((s, e))
        if e1 < e2:
            i += 1
        else:
            j += 1
    return res

# Data definition
WORK_START = to_min("09:00")
WORK_END = to_min("17:00")
MEETING_DUR = 30  # minutes

# Blocked intervals per person per day (strings)
blocked_raw = {
    "Margaret": {
        "Monday": [("10:30", "11:00"), ("11:30", "12:00"), ("13:00", "13:30"), ("15:00", "17:00")],
        "Tuesday": [("12:00", "12:30")]
    },
    "Alexis": {
        "Monday": [("09:30", "11:30"), ("12:30", "13:00"), ("14:00", "17:00")],
        "Tuesday": [("09:00", "09:30"), ("10:00", "10:30"), ("14:00", "16:30")]
    }
}

# Preferences / constraints
# Days a participant does NOT want to meet (global exclusion)
day_exclusions = {"Margaret": {"Monday"}}
# Earliest start per day (if any)
earliest_start = {
    "Tuesday": to_min("14:30")  # Margaret does not want Tuesday before 14:30
}

# Process each day
for day in ["Monday", "Tuesday"]:
    # skip day if any participant excludes it
    if any(day in excl for excl in day_exclusions.values()):
        continue

    # compute free intervals for each participant
    all_free = []
    for person, days in blocked_raw.items():
        occupied = [(to_min(s), to_min(e)) for s, e in days.get(day, [])]
        free = complement(occupied, WORK_START, WORK_END)
        # apply earliest start constraint if exists for this day
        if day in earliest_start:
            es = earliest_start[day]
            free = [(max(s, es), e) for s, e in free if e - max(s, es) >= MEETING_DUR]
        all_free.append(free)

    # intersect all participants' free intervals
    common = all_free[0]
    for other in all_free[1:]:
        common = intersect_two(common, other)
        if not common:
            break

    # find first interval with enough length
    for s, e in common:
        if e - s >= MEETING_DUR:
            start = s
            end = s + MEETING_DUR
            print([day, to_str(start), to_str(end)])
