import sys
from datetime import timedelta

# Helper to convert "H:MM" or "HH:MM" to minutes since midnight
def to_min(t):
    h, m = map(int, t.split(':'))
    return h * 60 + m

# Helper to convert minutes to "HH:MM"
def to_str(m):
    h = m // 60
    mi = m % 60
    return f"{h:02d}:{mi:02d}"

# Work hours (inclusive start, exclusive end)
WORK_START = to_min("09:00")
WORK_END = to_min("17:00")
MEETING_LEN = 30  # minutes

# Busy schedules per person per day
busy = {
    "Betty": {
        "Monday":   [("10:00","10:30"), ("13:30","14:00"), ("15:00","15:30"), ("16:00","16:30")],
        "Tuesday":  [("09:00","09:30"), ("11:30","12:00"), ("12:30","13:00"), ("13:30","14:00"), ("16:30","17:00")],
        "Wednesday":[("09:30","10:30"), ("13:00","13:30"), ("14:00","14:30")],
        "Thursday": [("09:30","10:00"), ("11:30","12:00"), ("14:00","14:30"), ("15:00","15:30"), ("16:30","17:00")]
    },
    "Scott": {
        "Monday":   [("09:30","15:00"), ("15:30","16:00"), ("16:30","17:00")],
        "Tuesday":  [("09:00","09:30"), ("10:00","11:00"), ("11:30","12:00"), ("12:30","13:30"),
                     ("14:00","15:00"), ("16:00","16:30")],
        "Wednesday":[("09:30","12:30"), ("13:00","13:30"), ("14:00","14:30"),
                     ("15:00","15:30"), ("16:00","16:30")],
        "Thursday": [("09:00","09:30"), ("10:00","10:30"), ("11:00","12:00"),
                     ("12:30","13:00"), ("15:00","16:00"), ("16:30","17:00")]
    }
}

# Convert all busy intervals to minute ranges
for person in busy:
    for day in busy[person]:
        busy[person][day] = [(to_min(s), to_min(e)) for s, e in busy[person][day]]

# Days to consider
days = ["Monday", "Tuesday", "Wednesday", "Thursday"]

# Betty's additional constraints (hard)
def betty_allowed(day, start_min):
    if day == "Monday":
        return False
    if day == "Tuesday":
        return False
    if day == "Thursday" and start_min < to_min("15:00"):
        return False
    return True

# Compute free intervals for person on a day within work hours
def free_intervals(person, day):
    intervals = []
    busy_list = busy[person].get(day, [])
    # sort busy intervals
    busy_list = sorted(busy_list)
    cursor = WORK_START
    for s, e in busy_list:
        if s > cursor:
            intervals.append((cursor, s))
        cursor = max(cursor, e)
    if cursor < WORK_END:
        intervals.append((cursor, WORK_END))
    return intervals

# Intersection of two interval lists
def intersect(a, b):
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s + MEETING_LEN <= e:
            res.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

# Find first feasible slot respecting preferences (avoid Wednesday if possible)
candidates = []
for day in days:
    for b_start, b_end in free_intervals("Betty", day):
        for s_start, s_end in free_intervals("Scott", day):
            # intersect the two free intervals
            for inter_start, inter_end in intersect([(b_start, b_end)], [(s_start, s_end)]):
                # slide a window of meeting length across the intersected interval
                t = max(inter_start, WORK_START)
                while t + MEETING_LEN <= inter_end:
                    if betty_allowed(day, t):
                        candidates.append((day, t))
                        break  # earliest slot for this day
                    t += 1
            if candidates and candidates[-1][0] == day:
                break
        if candidates and candidates[-1][0] == day:
            break

# Prefer Thursday over Wednesday (avoid Wednesday)
selected = None
for pref_day in ["Thursday", "Wednesday"]:
    for cand in candidates:
        if cand[0] == pref_day:
            selected = cand
            break
    if selected:
        break

# Fallback: any candidate
if not selected and candidates:
    selected = candidates[0]

day, start_min = selected
end_min = start_min + MEETING_LEN
print([day, to_str(start_min), to_str(end_min)])

