def to_minutes(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_time(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

# Define workday bounds (inclusive start, exclusive end)
WORK_START = to_minutes("09:00")
WORK_END = to_minutes("17:00")

# Meeting duration in minutes
DURATION = 60

# Busy schedules for each participant (day -> list of (start, end) strings)
busy = {
    "Patricia": {
        "Monday": [("10:00", "10:30"), ("11:30", "12:00"), ("13:00", "13:30"),
                   ("14:30", "15:30"), ("16:00", "16:30")],
        "Tuesday": [("10:00", "10:30"), ("11:00", "12:00"),
                    ("14:00", "16:00"), ("16:30", "17:00")]
    },
    "Jesse": {
        "Monday": [("09:00", "17:00")],
        "Tuesday": [("11:00", "11:30"), ("12:00", "12:30"),
                    ("13:00", "14:00"), ("14:30", "15:00"),
                    ("15:30", "17:00")]
    }
}

# Convert busy intervals to minutes and sort them
for person in busy:
    for day in busy[person]:
        busy[person][day] = sorted(
            [(to_minutes(s), to_minutes(e)) for s, e in busy[person][day]],
            key=lambda x: x[0]
        )

# Compute free intervals for a participant on a given day
def free_intervals(busy_intervals):
    free = []
    start = WORK_START
    for b_start, b_end in busy_intervals:
        if start < b_start:
            free.append((start, b_start))
        start = max(start, b_end)
    if start < WORK_END:
        free.append((start, WORK_END))
    return free

# Intersect two lists of intervals
def intersect(a, b):
    i, j = 0, 0
    result = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            result.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return result

# Days to consider (order matters for deterministic output)
days = ["Monday", "Tuesday"]

solution = None
for day in days:
    # Gather free intervals for each participant on this day
    participants_free = []
    for person in busy:
        busy_ints = busy[person].get(day, [])
        participants_free.append(free_intervals(busy_ints))
    # Intersect free intervals across all participants
    common = participants_free[0]
    for other in participants_free[1:]:
        common = intersect(common, other)
        if not common:
            break
    # Find a slot long enough
    for s, e in common:
        if e - s >= DURATION:
            solution = (day, to_time(s), to_time(s + DURATION))
            break
    if solution:
        break

# Print result in required format
print([solution[0], solution[1], solution[2]])

