from datetime import datetime, timedelta

# Helper functions
def to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m: int) -> str:
    h, m = divmod(m, 60)
    return f"{h:02d}:{m:02d}"

def merge_intervals(intervals):
    """Merge overlapping or adjacent intervals."""
    if not intervals:
        return []
    intervals.sort()
    merged = [intervals[0]]
    for start, end in intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:  # overlap or touch
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged

def complement(intervals, lo, hi):
    """Return gaps between lo..hi not covered by intervals."""
    free = []
    prev = lo
    for start, end in intervals:
        if start > prev:
            free.append((prev, start))
        prev = max(prev, end)
    if prev < hi:
        free.append((prev, hi))
    return free

# Data definition
work_start = to_min("09:00")
work_end   = to_min("17:00")
days = ["Monday", "Tuesday", "Wednesday", "Thursday"]

# Schedules (occupied times) for each participant
