        "Thursday":  [("10:00", "12:00"), ("14:00", "14:30"),
                      ("15:30", "16:00"), ("16:30", "17:00")],
    },
}

# Convert all times to minutes and merge per day across participants
occupied_by_day = {day: [] for day in days}
for person, day_map in schedules.items():
    for day, intervals in day_map.items():
        for s, e in intervals:
            occupied_by_day[day].append((to_min(s), to_min(e)))

# Find earliest common free slot of required duration (30 minutes)
required = 30
answer = None
for day in days:
    merged = merge_intervals(occupied_by_day[day])
    free = complement(merged, work_start, work_end)
    for start, end in free:
        if end - start >= required:
            answer = (day, to_str(start), to_str(start + required))
            break
    if answer:
        break

# Output in requested format
print([answer[0], answer[1], answer[2]])

