def to_min(t):
    h,m = map(int, t.split(':'))
    return h*60 + m

def from_min(m):
    h = m // 60
    mi = m % 60
    return f"{h:02d}:{mi:02d}"

def build_free(day):
    # start with whole work interval as free
    free = [(work_start, work_end)]
    for person in busy:
        for interval in busy[person].get(day, []):
            b_start, b_end = map(to_min, interval)
            # subtract this busy interval from free list
            new_free = []
            for f_start, f_end in free:
                if b_end <= f_start or b_start >= f_end:
                    new_free.append((f_start, f_end))
                else:
                    if b_start > f_start:
                        new_free.append((f_start, b_start))
                    if b_end < f_end:
                        new_free.append((b_end, f_end))
            free = new_free
    return sorted(free)

