    # Prefer non‑Wednesday days, then Wednesday as last resort
    for day in weekdays:
        if day == 'Wednesday':
            continue
        for start, end in build_free(day):
            if end - start >= duration_min:
                return day, start, start + duration_min
    # fallback to Wednesday
    day = 'Wednesday'
    for start, end in build_free(day):
        if end - start >= duration_min:
            return day, start, start + duration_min
    return None

