# John has no meetings, but prefers not to meet on Monday after 14:30
def is_preferred(day, start):
    if day == "Monday" and start > datetime.strptime("14:30", "%H:%M").time():
        return False
    return True

def parse_time(t):
    return datetime.strptime(t, "%H:%M").time()

def add_minutes(t, mins):
    dt = datetime.combine(datetime.today(), t) + timedelta(minutes=mins)
    return dt.time()

def free_intervals(busy):
    # busy: list of (start_str, end_str) sorted, within work hours
    free = []
    cur = work_start
    for s_str, e_str in busy:
        s = parse_time(s_str)
        e = parse_time(e_str)
        if s > cur:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < work_end:
        free.append((cur, work_end))
    return free

def find_slot():
    for day in ["Monday", "Tuesday", "Wednesday"]:
        busy = sorted(jen_busy.get(day, []), key=lambda x: x[0])
        free = free_intervals(busy)
        for start, end in free:
            # generate possible start times within this free window
            start_dt = datetime.combine(datetime.min, start)
            end_dt = datetime.combine(datetime.min, end)
            while start_dt + duration <= end_dt:
                start_time = start_dt.time()
                end_time = (start_dt + duration).time()
                if is_preferred(day, start_time):
                    return [day, start_time.strftime("%H:%M"), end_time.strftime("%H:%M")]
                start_dt += timedelta(minutes=1)
    return None

