pref_latest_start = {"Monday": "14:00"}

# ---------- Helpers ----------
def to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m: int) -> str:
    return f"{m//60:02d}:{m%60:02d}"

def complement(busy, day):
    """Return list of free intervals within work hours for a given day."""
    w_start = to_min(work_start)
    w_end = to_min(work_end)
    intervals = [(w_start, w_end)]
    for d, s, e in busy:
        if d != day:
            continue
        s_min, e_min = to_min(s), to_min(e)
        new_intervals = []
        for a, b in intervals:
            if e_min <= a or s_min >= b:
                new_intervals.append((a, b))
            else:
                if a < s_min:
                    new_intervals.append((a, s_min))
                if e_min < b:
                    new_intervals.append((e_min, b))
        intervals = new_intervals
    intervals.sort()
    return intervals

def intersect_two(a, b):
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        start = max(a[i][0], b[j][0])
        end = min(a[i][1], b[j][1])
        if start < end:
            res.append((start, end))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

def intersect_all(lists):
    if not lists:
        return []
    res = lists[0]
    for lst in lists[1:]:
        res = intersect_two(res, lst)
        if not res:
            break
