# Helper functions
def to_min(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_str(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

def subtract_interval(free, busy):
    """Subtract a busy interval from a list of free intervals."""
    result = []
    b_start, b_end = busy
    for f_start, f_end in free:
        if b_end <= f_start or b_start >= f_end:
            # no overlap
            result.append((f_start, f_end))
        else:
            # overlap exists, possibly split
            if b_start > f_start:
                result.append((f_start, b_start))
            if b_end < f_end:
                result.append((b_end, f_end))
    return result

def intersect_two(a, b):
    """Intersect two lists of intervals."""
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        a_start, a_end = a[i]
        b_start, b_end = b[j]
        start = max(a_start, b_start)
        end = min(a_end, b_end)
        if start < end:
            res.append((start, end))
        if a_end <= b_end:
            i += 1
        else:
            j += 1
    return res

