import sys

# Helper functions
def hm_to_min(t):
    h, m = map(int, t.split(":"))
    return h * 60 + m

def min_to_hm(m):
    h = m // 60
    mi = m % 60
    return f"{h:02d}:{mi:02d}"

def complement(busy, work_start, work_end):
    """Return free intervals within [work_start, work_end) given busy list sorted, non‑overlapping."""
    free = []
    cur = work_start
    for b_start, b_end in busy:
        if b_start > cur:
            free.append((cur, b_start))
        cur = max(cur, b_end)
    if cur < work_end:
        free.append((cur, work_end))
    return free

def intersect(a, b):
    """Yield intersections of two interval lists."""
    i = j = 0
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            yield (s, e)
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1

