def merge_intervals(intervals):
    """Merge overlapping intervals; intervals are (start_time, end_time) as time objects."""
    if not intervals:
        return []
    sorted_ints = sorted(intervals, key=lambda x: x[0])
    merged = [sorted_ints[0]]
    for cur_start, cur_end in sorted_ints[1:]:
        last_start, last_end = merged[-1]
        if cur_start <= last_end:  # overlap
            merged[-1] = (last_start, max(last_end, cur_end))
        else:
            merged.append((cur_start, cur_end))
    return merged

