                          datetime.strptime(e, "%H:%M").time())
                         for s, e in busy[person].get(day, [])]
            all_busy.append(merge_intervals(intervals))
        # compute free intervals per participant
        frees = [invert_busy(p_busy) for p_busy in all_busy]
        # intersect free intervals across participants
        # start with frees[0], iteratively intersect with others
        intersect = frees[0]
        for other in frees[1:]:
            new_inter = []
            i = j = 0
            while i < len(intersect) and j < len(other):
                a_start, a_end = intersect[i]
                b_start, b_end = other[j]
                # find overlap
                start = max(a_start, b_start)
                end   = min(a_end, b_end)
                if start < end:
                    new_inter.append((start, end))
                # advance pointer with earlier end
                if a_end <= b_end:
                    i += 1
                else:
                    j += 1
            intersect = new_inter
            if not intersect:
                break
        # check each intersected free slot for enough length and preferences
        for start, end in intersect:
            slot_start = datetime.combine(datetime.today(), start)
            while slot_start + duration <= datetime.combine(datetime.today(), end):
