    "Wednesday": [("10:30", "11:00"), ("11:30", "12:00"), ("12:30", "13:00"),
                  ("14:00", "14:30"), ("15:00", "16:00")]
}
# Larry has no busy intervals
larry_busy = {day: [] for day in ["Monday", "Tuesday", "Wednesday"]}

# Preference ordering (higher priority first)
day_order = ["Monday", "Tuesday", "Wednesday"]  # Wednesday is least preferred, Tuesday less preferred than Monday

def parse_time(t):
    return datetime.strptime(t, "%H:%M")

def complement_intervals(busy, day):
    """Return free intervals within work hours for a given day."""
    # Start with whole work interval
    free = [(parse_time(work_start.strftime("%H:%M")), parse_time(work_end.strftime("%H:%M")))]
    # Convert busy intervals to datetime objects
    busy_dt = [(parse_time(s), parse_time(e)) for s, e in busy]
    # Subtract each busy interval from current free list
    result = []
    for f_start, f_end in free:
        cur_start = f_start
        for b_start, b_end in sorted(busy_dt):
            if b_end <= cur_start or b_start >= f_end:
                continue
            if b_start > cur_start:
                result.append((cur_start, b_start))
            cur_start = max(cur_start, b_end)
        if cur_start < f_end:
            result.append((cur_start, f_end))
    return result

def earliest_slot(free_intervals):
    """Find earliest slot of required duration in a list of free intervals."""
    for start, end in free_intervals:
        if end - start >= meeting_duration:
            slot_end = start + meeting_duration
            return start.time(), slot_end.time()
    return None

def format_time(t):
    return t.strftime("%H:%M")

# Compute combined free slots for both participants per day
for day in day_order:
    # Merge busy lists
    combined_busy = samuel_busy.get(day, []) + larry_busy.get(day, [])
    free = complement_intervals(combined_busy, day)
    slot = earliest_slot(free)
    if slot:
        start_str, end_str = format_time(slot[0]), format_time(slot[1])
        print([day, start_str, end_str])
        break
